-- =============================================================================
-- DDI 支持药物白名单（由 scripts 一次性生成，勿手改）
--
-- 为什么需要这张表：DDI-LLM 是**转导式**（transductive）模型，只学到训练图内节点的
-- embedding，图外药物在数学上无法预测。所以'能预测哪些药物'是模型的硬能力边界，
-- 必须显式落库，而不是靠调用方猜。
--
-- 生成来源：weights/ddi_gcn_morgan.pt 的 node_id_map（图内节点）
--           join data/Drug_description.csv（药名）
--           join data/structure_links.csv（SMILES）
--
-- smiles_hash = SHA-256(去掉所有空白字符的 SMILES)，用于后端把用户输入的 SMILES
-- 反查成 DrugBank ID。两侧规范化规则必须一致（见 DdiDrugResolver）。
-- =============================================================================

CREATE TABLE IF NOT EXISTS ddi_supported_drug (
    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
    drugbank_id VARCHAR(20)  NOT NULL COMMENT 'DrugBank ID，DDI 模型图内节点标识',
    drug_name   VARCHAR(255) DEFAULT NULL COMMENT '药物名称',
    smiles      VARCHAR(1500) DEFAULT NULL COMMENT '原始 SMILES（展示用）',
    smiles_hash CHAR(64)     DEFAULT NULL COMMENT '规范化 SMILES 的 SHA-256，用于反查',
    created_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uk_drugbank_id (drugbank_id),
    KEY idx_smiles_hash (smiles_hash),
    KEY idx_drug_name (drug_name)
) COMMENT='DDI-LLM 支持的药物白名单（转导式模型能力边界）';

